1	/**
2	 * Modal de bip dentro da Separação Digital (PaginaPicking).
3	 *
4	 * Operador bipa cada caixa que vai entrar no pedido. Para cada UID:
5	 *  1. Pré-fetch etiquetas_qr pra saber quantidade_interna (não muta status)
6	 *  2. Se nova_qtd > pedido → AlertDialog de excesso (CTO: aceita com confirmação)
7	 *  3. RPC bipar_etiqueta(uid,'separacao', {requisicao_id}) — valida + transição
8	 *  4. Acha item por produto_master_id
9	 *  5. Incrementa quantidade_enviada do item (qty da embalagem do QR)
10	 *  6. Reaproveita selectedBatches com lote do QR
11	 *  7. Chama onBip — PaginaPicking persiste via updateItemEnviada existente
12	 *
13	 * UI mostra progresso por item: caixas bipadas + un acumuladas lado-a-lado.
14	 */
15	import { useMemo, useRef, useState } from "react";
16	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
17	import { Button } from "@/shared/ui/button";
18	import { ScrollArea } from "@/shared/ui/scroll-area";
19	import {
20	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
21	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
22	} from "@/shared/ui/alert-dialog";
23	import {
24	  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, CheckCircle2, AlertTriangle, Boxes,
25	} from "lucide-react";
26	import { toast } from "sonner";
27	import { cn } from "@/shared/lib/utils";
28	import { supabase } from "@/integrations/supabase/client";
29	import {
30	  useEtiquetaScanner,
31	  playSuccessSound,
32	  playErrorSound,
33	  playWarningSound,
34	  formatBipError,
35	  calcularIncrementoBip,
36	  type ScannedPayload,
37	} from "@/shared/hooks/useEtiquetaScanner";
38	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
39	
40	export interface PickingBipItem {
41	  id: number;
42	  produto_nome: string;
43	  masterId?: number;
44	  quantidade: number;
45	  quantidade_enviada?: string;
46	  coletado: boolean;
47	  selectedBatches?: Record<string, number>;
48	  availableBatches?: Array<{ id: string; lote_id: string; quantidade: number; lotes: { id: string; codigo: string } }>;
49	  // Unidade do PEDIDO. Decide se cada bip soma +1 (caixa) ou +quantidade_interna (kg, un).
50	  unidade_medida?: string | null;
51	}
52	
53	
54	export interface BipApplied {
55	  itemId: number;
56	  produtoNome: string;
57	  uid: string;
58	  qty: number;
59	  /** Unidade INTERNA da etiqueta (un, kg, g). Em "Caixa com 12 un" = "un". */
60	  embalagem: string | null;
61	  /** Tipo do CONTAINER físico (caixa, saco, balde…). Usado na UI ao invés de embalagem. */
62	  tipoEmbalagem: string | null;
63	  /** Qty INTERNA da etiqueta (12, 5, etc). Pra mostrar "1 caixa (12 un)". */
64	  qtyInterna: number;
65	  loteId: string | null;
66	  bipadoAt: number;
67	}
68	
69	interface ExcessoState {
70	  open: boolean;
71	  produtoNome: string;
72	  pedidoQtd: number;
73	  jaEnviado: number;
74	  etiquetaQtd: number;
75	  sobra: number;
76	  resolve?: (ok: boolean) => void;
77	}
78	
79	interface Props {
80	  isOpen: boolean;
81	  onClose: () => void;
82	  items: PickingBipItem[];
83	  requisicaoId: string | number;
84	  onApply: (itemId: number, novaQuantidade: string, batches?: Record<string, number>) => Promise<void> | void;
85	  defaultMode?: "bluetooth" | "camera";
86	}
87	
88	export function PickingBipModal({ isOpen, onClose, items, requisicaoId, onApply, defaultMode = "bluetooth" }: Props) {
89	  const [aplicados, setAplicados] = useState<BipApplied[]>([]);
90	  const uidsLidosRef = useRef<Set<string>>(new Set());
91	  const [excesso, setExcesso] = useState<ExcessoState>({
92	    open: false, produtoNome: "", pedidoQtd: 0, jaEnviado: 0, etiquetaQtd: 0, sobra: 0,
93	  });
94	  // Dialog de transferir separacao quando etiqueta ja foi separada em outra req
95	  const [reseparirDialog, setReseparirDialog] = useState<{
96	    open: boolean;
97	    uid: string;
98	    produto: string;
99	    separada_at: string | null;
100	    payload: ScannedPayload | null;
101	  }>({ open: false, uid: "", produto: "", separada_at: null, payload: null });
102	
103	  const handleBip = async (payload: ScannedPayload) => {
104	    if (!payload.uid) {
105	      playErrorSound();
106	      toast.error("Etiqueta sem UID — não rastreável");
107	      return;
108	    }
109	    if (uidsLidosRef.current.has(payload.uid)) {
110	      playErrorSound();
111	      toast.error("Caixa já bipada nesta separação");
112	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
113	      return;
114	    }
115	
116	    // ── Pré-fetch sem mutar status: precisa saber quantidade_interna pra checar excesso
117	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
118	    const { data: pre } = await (supabase
119	      .from("etiquetas_qr") as any)
120	      .select("produto_master_id, produto_nome_snapshot, quantidade_interna, embalagem_nome, tipo_embalagem, lote_id, status")
121	      .eq("uid", payload.uid)
122	      .maybeSingle();
123	
124	    const preEt = pre as
125	      | { produto_master_id: number; produto_nome_snapshot?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; lote_id?: string | null; status?: string }
126	      | null;
127	
128	    const qtyEtiqueta = Number(preEt?.quantidade_interna ?? payload.qty ?? 1);
129	    const tipoEmbEtq = preEt?.tipo_embalagem ?? null;
130	    const pidEstimado = Number(preEt?.produto_master_id ?? payload.pid ?? 0);
131	    const nomeEstimado = preEt?.produto_nome_snapshot || `Produto #${pidEstimado || "?"}`;
132	
133	    // ── Excesso: se item da req achado e nova_qtd > pedido, pedir confirmação
134	    const target = items.find((i) => i.masterId === pidEstimado);
135	    // Regra universal: pedido bate com tipo da etiqueta → +1; senão → +qty_interna
136	    const qtyEstimada = target ? calcularIncrementoBip(target.unidade_medida, tipoEmbEtq, qtyEtiqueta) : qtyEtiqueta;
137	    if (target) {
138	      const aplicadosNoItem = aplicados.filter((a) => a.itemId === target.id);
139	      const baseAtual = aplicadosNoItem.length === 0
140	        ? Number(target.quantidade_enviada || 0)
141	        : aplicadosNoItem.reduce((acc, a) => acc + a.qty, Number(target.quantidade_enviada || 0));
142	      const novaQtdPrev = baseAtual + qtyEstimada;
143	      if (novaQtdPrev > target.quantidade) {
144	        const sobra = novaQtdPrev - target.quantidade;
145	        const confirmed = await new Promise<boolean>((resolve) => {
146	          setExcesso({
147	            open: true,
148	            produtoNome: target.produto_nome,
149	            pedidoQtd: target.quantidade,
150	            jaEnviado: baseAtual,
151	            etiquetaQtd: qtyEstimada,
152	            sobra,
153	            resolve,
154	          });
155	        });
156	        if (!confirmed) {
157	          // Não chamou RPC ainda — etiqueta segue intacta no banco
158	          return;
159	        }
160	      }
161	    }
162	
163	    // ── RPC = source of truth de validação
164	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
165	    const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
166	      p_uid: payload.uid,
167	      p_etapa: "separacao",
168	      p_contexto: {
169	        referencia_tipo: "requisicao",
170	        referencia_id: String(requisicaoId),
171	        payload,
172	      },
173	    });
174	    if (rpcErr) {
175	      playErrorSound();
176	      toast.error(`Falha no bip: ${rpcErr.message}`);
177	      return;
178	    }
179	    const result = rpcRaw as {
180	      ok: boolean;
181	      erro?: string;
182	      etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; lote_id?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; separada_at?: string | null };
183	      alertas?: string[];
184	    };
185	    if (!result?.ok || !result.etiqueta) {
186	      // Caso especial: ja separada → abrir dialog pra transferir pra essa requisicao
187	      const erroLower = (result?.erro || "").toLowerCase();
188	      const isJaSeparada = erroLower.includes('"separada"') || erroLower.includes("separada");
189	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
190	      const etSep = result?.etiqueta as any;
191	      if (isJaSeparada && etSep?.separada_at) {
192	        playWarningSound();
193	        setReseparirDialog({
194	          open: true,
195	          uid: payload.uid,
196	          produto: etSep.produto_nome_snapshot || "produto",
197	          separada_at: etSep.separada_at,
198	          payload,
199	        });
200	        return;
201	      }
202	      playErrorSound();
203	      toast.error(formatBipError(result?.erro, "separacao", result?.etiqueta));
204	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
205	      return;
206	    }
207	    (result.alertas ?? []).forEach((a) => {
208	      playWarningSound();
209	      toast.warning(a);
210	    });
211	
212	    const scannedPid = result.etiqueta.produto_master_id;
213	    const qtyEtiquetaReal = Number(result.etiqueta.quantidade_interna ?? payload.qty ?? 1);
214	    const scannedLote = result.etiqueta.lote_id ?? null;
215	    const scannedEmb = result.etiqueta.embalagem_nome ?? preEt?.embalagem_nome ?? null;
216	    const scannedNome = result.etiqueta.produto_nome_snapshot || nomeEstimado;
217	
218	    const targetReal = items.find((i) => i.masterId === scannedPid);
219	    if (!targetReal) {
220	      // Item nao esta na lista → silenciosamente registra e segue. Operador
221	      // pode confirmar excesso atraves do AlertDialog se quiser forcar.
222	      // Toast removido (era ruido — sempre aparecia mesmo em fluxo normal de excesso).
223	      uidsLidosRef.current.add(payload.uid);
224	      return;
225	    }
226	
227	    // Regra universal: pedido bate com tipo da etiqueta → +1, senão → +qty real
228	    const scannedTipoEmb = result.etiqueta.tipo_embalagem ?? tipoEmbEtq;
229	    const scannedQty = calcularIncrementoBip(targetReal.unidade_medida, scannedTipoEmb, qtyEtiquetaReal);
230	
231	    const aplicadosNoItem = aplicados.filter((a) => a.itemId === targetReal.id);
232	    const baseAtual = aplicadosNoItem.length === 0
233	      ? Number(targetReal.quantidade_enviada || 0)
234	      : aplicadosNoItem.reduce((acc, a) => acc + a.qty, Number(targetReal.quantidade_enviada || 0));
235	    const novaQtdNum = baseAtual + scannedQty;
236	
237	    // Selected batches sempre rastreia a qty FISICA da etiqueta (pro estoque por lote
238	    // ficar correto independente de unidade do pedido — lote conta unidades reais).
239	    const batchesNovo: Record<string, number> = { ...(targetReal.selectedBatches || {}) };
240	    if (scannedLote) {
241	      batchesNovo[scannedLote] = (batchesNovo[scannedLote] || 0) + qtyEtiquetaReal;
242	    }
243	
244	    try {
245	      await onApply(targetReal.id, String(novaQtdNum), Object.keys(batchesNovo).length ? batchesNovo : undefined);
246	    } catch (e) {
247	      playErrorSound();
248	      toast.error(`Erro ao salvar: ${(e as Error).message}`);
249	      return;
250	    }
251	
252	    playSuccessSound();
253	    if (navigator.vibrate) navigator.vibrate(80);
254	    // Toast mostra "+1 caixa" usando o TIPO da etiqueta (caixa/saco/balde) — nunca "un"
255	    const tipoLabel = (scannedTipoEmb || targetReal.unidade_medida || 'cx').toLowerCase();
256	    toast.success(`${scannedNome} +${scannedQty} ${tipoLabel}`);
257	
258	    setAplicados((prev) => [
259	      {
260	        itemId: targetReal.id,
261	        produtoNome: targetReal.produto_nome,
262	        uid: payload.uid,
263	        qty: scannedQty,
264	        embalagem: scannedEmb,
265	        tipoEmbalagem: scannedTipoEmb,
266	        qtyInterna: qtyEtiquetaReal,
267	        loteId: scannedLote,
268	        bipadoAt: Date.now(),
269	      },
270	      ...prev,
271	    ]);
272	    uidsLidosRef.current.add(payload.uid);
273	  };
274	
275	  const scanner = useEtiquetaScanner({
276	    enabled: isOpen,
277	    onScan: handleBip,
278	    onInvalid: () => {
279	      toast.error("QR ilegível");
280	    },
281	    onDuplicate: () => {
282	      playErrorSound();
283	      toast.error("Esta etiqueta já foi bipada");
284	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
285	    },
286	    cameraElementId: "picking-bip-camera",
287	    initialMode: defaultMode,
288	  });
289	
290	  // Progresso por item — caixas bipadas + un acumuladas
291	  const progressoPorItem = useMemo(() => {
292	    return items.map((item) => {
293	      const bipsItem = aplicados.filter((a) => a.itemId === item.id);
294	      const caixas = bipsItem.length;
295	      const unBipadas = bipsItem.reduce((acc, b) => acc + b.qty, 0);
296	      const unBaseInicial = bipsItem.length === 0 ? Number(item.quantidade_enviada || 0) : 0;
297	      const totalUn = unBipadas + unBaseInicial;
298	      const pedidoUn = item.quantidade || 0;
299	      const pct = pedidoUn > 0 ? Math.min(100, Math.round((totalUn / pedidoUn) * 100)) : 0;
300	      const status: "vazio" | "parcial" | "completo" | "excesso" =
301	        totalUn === 0 ? "vazio"
302	          : totalUn > pedidoUn ? "excesso"
303	          : totalUn >= pedidoUn ? "completo"
304	          : "parcial";
305	      return { item, caixas, unBipadas, totalUn, pedidoUn, pct, status };
306	    });
307	  }, [items, aplicados]);
308	
309	  const stats = useMemo(() => {
310	    const completos = progressoPorItem.filter((p) => p.status === "completo" || p.status === "excesso").length;
311	    const totalUnSolicitado = progressoPorItem.reduce((acc, p) => acc + p.pedidoUn, 0);
312	    const totalUnEnviado = progressoPorItem.reduce((acc, p) => acc + p.totalUn, 0);
313	    const totalCaixas = aplicados.length;
314	    return {
315	      completos,
316	      itensTotais: items.length,
317	      bipsAplicados: aplicados.length,
318	      totalCaixas,
319	      totalUnSolicitado,
320	      totalUnEnviado,
321	    };
322	  }, [items, aplicados, progressoPorItem]);
323	
324	  // Transferir separacao da req anterior pra esta — sobrescreve separada_at/por
325	  // e aplica o bip visualmente igual ao fluxo normal de sucesso.
326	  const confirmarReseparar = async () => {
327	    if (!reseparirDialog.uid || !reseparirDialog.payload) {
328	      setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null });
329	      return;
330	    }
331	    const payload = reseparirDialog.payload;
332	    try {
333	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
334	      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta_reseparar", {
335	        p_uid: reseparirDialog.uid,
336	        p_contexto: {
337	          referencia_tipo: "requisicao",
338	          referencia_id: String(requisicaoId),
339	          payload,
340	        },
341	      });
342	      const rpc = rpcRaw as { ok: boolean; erro?: string; etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; lote_id?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null } } | null;
343	      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
344	        toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir separação");
345	        playErrorSound();
346	        return;
347	      }
348	
349	      // Aplica visualmente o bip — replica logica do handleBip apos sucesso da RPC
350	      const scannedPid = rpc.etiqueta.produto_master_id;
351	      const qtyEtiquetaReal = Number(rpc.etiqueta.quantidade_interna ?? payload.qty ?? 1);
352	      const scannedLote = rpc.etiqueta.lote_id ?? null;
353	      const scannedEmb = rpc.etiqueta.embalagem_nome ?? null;
354	      const scannedTipoEmb = rpc.etiqueta.tipo_embalagem ?? payload.tipo ?? null;
355	      const scannedNome = rpc.etiqueta.produto_nome_snapshot || reseparirDialog.produto;
356	
357	      const targetReal = items.find((i) => i.masterId === scannedPid);
358	      if (!targetReal) {
359	        uidsLidosRef.current.add(payload.uid);
360	        toast.warning(`${scannedNome} transferido mas NÃO está na lista — registrado como extra`);
361	        return;
362	      }
363	      const scannedQty = calcularIncrementoBip(targetReal.unidade_medida, scannedTipoEmb, qtyEtiquetaReal);
364	      const aplicadosNoItem = aplicados.filter((a) => a.itemId === targetReal.id);
365	      const baseAtual = aplicadosNoItem.length === 0
366	        ? Number(targetReal.quantidade_enviada || 0)
367	        : aplicadosNoItem.reduce((acc, a) => acc + a.qty, Number(targetReal.quantidade_enviada || 0));
368	      const novaQtdNum = baseAtual + scannedQty;
369	      const batchesNovo: Record<string, number> = { ...(targetReal.selectedBatches || {}) };
370	      if (scannedLote) batchesNovo[scannedLote] = (batchesNovo[scannedLote] || 0) + qtyEtiquetaReal;
371	
372	      await onApply(targetReal.id, String(novaQtdNum), Object.keys(batchesNovo).length ? batchesNovo : undefined);
373	      playSuccessSound();
374	      if (navigator.vibrate) navigator.vibrate(100);
375	      toast.success(`Separação transferida: ${scannedNome}`);
376	      setAplicados((prev) => [
377	        {
378	          itemId: targetReal.id, produtoNome: targetReal.produto_nome,
379	          uid: payload.uid, qty: scannedQty,
380	          embalagem: scannedEmb, tipoEmbalagem: scannedTipoEmb,
381	          qtyInterna: qtyEtiquetaReal, loteId: scannedLote, bipadoAt: Date.now(),
382	        },
383	        ...prev,
384	      ]);
385	      uidsLidosRef.current.add(payload.uid);
386	    } catch (e) {
387	      toast.error(`Erro: ${(e as Error).message}`);
388	      playErrorSound();
389	    } finally {
390	      setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null });
391	    }
392	  };
393	
394	  return (
395	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
396	      <DialogContent data-mia-modal="separar-com-bip" className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none">
397	        {/* Header */}
398	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
399	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
400	            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
401	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
402	            </Button>
403	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
404	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
405	            </div>
406	            <div className="min-w-0 flex-1">
407	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">
408	                Separar com bip
409	              </DialogTitle>
410	              <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
411	                Aponte o leitor pra cada caixa que vai entrar no pedido
412	              </p>
413	            </div>
414	          </div>
415	          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
416	            <button
417	              onClick={() => scanner.setScanMode("bluetooth")}
418	              aria-label="Scanner Bluetooth"
419	              className={cn(
420	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
421	                scanner.scanMode === "bluetooth"
422	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
423	                  : "text-muted-foreground hover:text-foreground"
424	              )}
425	            >
426	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
427	            </button>
428	            <button
429	              onClick={() => scanner.setScanMode("camera")}
430	              aria-label="Scanner por câmera"
431	              className={cn(
432	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
433	                scanner.scanMode === "camera"
434	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
435	                  : "text-muted-foreground hover:text-foreground"
436	              )}
437	            >
438	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
439	            </button>
440	          </div>
441	        </div>
442	
443	        {/* Stats — caixas + qty lado-a-lado.
444	            Label "Enviado" eh generica porque a requisicao pode ter items em unidades
445	            diferentes (caixa + kg). Detalhe por unidade fica no ItemProgress de cada item. */}
446	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
447	          <Stat label="Itens completos" value={`${stats.completos}/${stats.itensTotais}`} />
448	          <Stat label="Bipados" value={String(stats.totalCaixas)} icon={<Boxes className="w-3 h-3" />} />
449	          <Stat label="Enviado" value={`${stats.totalUnEnviado}/${stats.totalUnSolicitado}`} />
450	          <Stat label="Bips" value={String(stats.bipsAplicados)} />
451	        </div>
452	
453	        {/* Scanner input invisível (Bluetooth) */}
454	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
455	
456	        {/* Body */}
457	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
